20		base := os.Getenv("XDG_CONFIG_HOME")
21		if base == "" {
22			home, _ := os.UserHomeDir()
23			base = filepath.Join(home, ".config")
24		}
25		return filepath.Join(base, "wire", "config.yaml")
26	}
27	
28	type Config struct {
29		Listen    string                 `yaml:"listen"`
30		Monitor   bool                   `yaml:"monitor"`
31		MaxModels int                    `yaml:"max_models"`
32		Models    map[string]ModelParams `yaml:"models"`
33		Warmup    []string               `yaml:"warmup"`
34	}
