36	type ModelParams struct {
37		Context    int      `yaml:"context"`
38		GPULayers  int      `yaml:"gpu_layers"`
39		Slots      int      `yaml:"slots"`
40		Pooling    string   `yaml:"pooling"`
41		Extra      []string `yaml:"extra"`
42		SpecType   string   `yaml:"spec_type"`
43		DraftMax   int      `yaml:"draft_max"`
44		DraftMin   int      `yaml:"draft_min"`
45		SpecNgramN int      `yaml:"spec_ngram_n"`
46		SpecNgramM int      `yaml:"spec_ngram_m"`
47	}
48	
49	// MatchModel returns the ModelParams for the first glob pattern in Models that
50	// matches name. Returns zero ModelParams and false if no pattern matches.
51	func (c *Config) MatchModel(name string) (ModelParams, bool) {
52		for pattern, params := range c.Models {
53			matched, err := filepath.Match(pattern, name)
54			if err == nil && matched {
55				return params, true
56			}
57		}
58		return ModelParams{}, false
59	}
60	
61	// Load reads the config from disk, applies defaults, and validates it.
62	func Load() (*Config, error) {
63		path := Path()
64	
65		data, err := os.ReadFile(path)
66		if err != nil {
67			if errors.Is(err, os.ErrNotExist) {
68				return nil, fmt.Errorf("config file not found at %s: %w", path, err)
69			}
70			return nil, fmt.Errorf("reading config %s: %w", path, err)
71		}
72	
73		cfg := new(Config)
74		dec := yaml.NewDecoder(bytes.NewReader(data))
75		dec.KnownFields(true)
76		if err := dec.Decode(cfg); err != nil {
77			return nil, fmt.Errorf("parsing config %s: %w", path, err)
78		}
79	
80		applyDefaults(cfg)
81	
82		if err := validate(cfg); err != nil {
83			return nil, err
84		}
85	
86		return cfg, nil
87	}
88	
89	func applyDefaults(cfg *Config) {
90		if cfg.Listen == "" {
91			cfg.Listen = ":9480"
92		}
93		if cfg.MaxModels == 0 {
94			cfg.MaxModels = 1
95		}
96		for pattern, p := range cfg.Models {
97			if p.Slots == 0 {
98				p.Slots = 1
99				cfg.Models[pattern] = p
100			}
101		}
102	}
103	
104	func validate(cfg *Config) error {
105		for _, entry := range cfg.Warmup {
106			var matches int
107			for pattern := range cfg.Models {
108				matched, err := filepath.Match(pattern, entry)
109				if err == nil && matched {
110					matches++
111				}
112			}
113			if matches == 0 {
114				return fmt.Errorf("warmup entry %q does not match any model pattern", entry)
115			}
116			if matches > 1 {
117				return fmt.Errorf("warmup entry %q matches %d model patterns (expected 1)", entry, matches)
118			}
119		}
120		if len(cfg.Warmup) > cfg.MaxModels {
121			return fmt.Errorf("warmup list length %d exceeds max_models %d", len(cfg.Warmup), cfg.MaxModels)
122		}
123		validSpecTypes := map[string]bool{
124			"ngram-simple":  true,
125			"ngram-mod":     true,
126			"ngram-cache":   true,
127			"ngram-map-k":   true,
128			"ngram-map-k4v": true,
129		}
130		for pattern, p := range cfg.Models {
131			if p.SpecType != "" && !validSpecTypes[p.SpecType] {
132				return fmt.Errorf("model pattern %q: invalid spec_type %q (valid: ngram-simple, ngram-mod, ngram-cache, ngram-map-k, ngram-map-k4v)", pattern, p.SpecType)
133			}
134		}
