3	import (
4		"bytes"
5		"context"
6		"encoding/json"
7		"errors"
8		"fmt"
9		"io"
10		"log/slog"
11		"net/http"
12		"net/http/httputil"
13		"net/url"
14		"time"
15	
16		"github.com/nogo/wire/internal/config"
17		"github.com/nogo/wire/internal/monitor"
18		"github.com/nogo/wire/internal/process"
19	)
20	
21	// nctxProvider wraps the NCtx lookup; *monitor.Hub satisfies this interface.
22	type nctxProvider interface {
23		NCtx(model string) int
24	}
25	
26	// backendManager is the subset of process.Manager the Gateway depends on.
27	type backendManager interface {
28		Loaded(name string) bool
29		// LoadOrGet returns the backend address for the named model, loading it on
30		// demand if not already running. The caller must call release() when the
31		// proxied request completes to decrement the in-flight counter.
32		LoadOrGet(ctx context.Context, modelName string, params config.ModelParams) (addr string, release func(), err error)
33		// ListModels returns all known models in non-idle states.
34		ListModels() []monitor.ModelInfo
35	}
36	
37	// Gateway is an HTTP reverse-proxy that routes OpenAI-compatible requests to llama-server processes.
38	type Gateway struct {
39		cfg      *config.Config
40		mgr      backendManager
41		log      *slog.Logger
42		affinity *affinityTable
43		hub      nctxProvider
44		server   *http.Server
45	}
46	
47	// New creates a Gateway backed by the given process manager.
48	// hub may be nil; when non-nil, /monitor and /monitor/ws routes are registered.
49	func New(cfg *config.Config, mgr *process.Manager, hub *monitor.Hub, log *slog.Logger) *Gateway {
50		return newGateway(cfg, mgr, hub, log)
51	}
52	
53	func newGateway(cfg *config.Config, mgr backendManager, hub *monitor.Hub, log *slog.Logger) *Gateway {
54		// Build affinity table from warmup models.
55		modelSlots := make(map[string]int, len(cfg.Warmup))
56		for _, name := range cfg.Warmup {
57			if params, ok := cfg.MatchModel(name); ok {
58				modelSlots[name] = params.Slots
59			}
60		}
61	
62		g := &Gateway{cfg: cfg, mgr: mgr, log: log, affinity: newAffinityTable(modelSlots)}
63		// Store hub as nctxProvider nil-safely: a nil *monitor.Hub must not become
64		// a non-nil interface value, which would cause g.hub == nil checks to fail.
65		if hub != nil {
66			g.hub = hub
67		}
68	
69		mux := http.NewServeMux()
70		mux.HandleFunc("POST /v1/chat/completions", g.handleRoute)
71		mux.HandleFunc("POST /v1/completions", g.handleRoute)
72		mux.HandleFunc("POST /v1/embeddings", g.handleRoute)
73		mux.HandleFunc("POST /v1/rerank", g.handleRoute)
74		mux.HandleFunc("GET /v1/models", g.handleModels)
75		mux.HandleFunc("GET /health", g.handleHealth)
76	
77		if hub != nil {
78			mux.HandleFunc("GET /monitor", monitor.HandlePage)
79			mux.HandleFunc("GET /monitor/ws", monitor.HandleWS(hub))
80		}
81	
82		g.server = &http.Server{Addr: cfg.Listen, Handler: mux}
83		return g
84	}
85	
86	// ListenAndServe starts the HTTP server and shuts it down when ctx is cancelled.
87	func (g *Gateway) ListenAndServe(ctx context.Context) error {
88		errCh := make(chan error, 1)
89		go func() {
90			if err := g.server.ListenAndServe(); err != nil && err != http.ErrServerClosed {
91				errCh <- err
92			}
93		}()
94		select {
95		case err := <-errCh:
96			return err
97		case <-ctx.Done():
98			shutCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
99			defer cancel()
100			return g.server.Shutdown(shutCtx)
101		}
102	}
103	
104	// handleRoute extracts the model field from the JSON body and proxies to the matching process.
105	// If the model is known but not loaded, it is started on demand; the HTTP connection
106	// is held open until the model becomes healthy.
107	func (g *Gateway) handleRoute(w http.ResponseWriter, r *http.Request) {
108		// Tee the body so the decoder and the upstream both see it.
109		var captured bytes.Buffer
110		tee := io.TeeReader(r.Body, &captured)
111		dec := json.NewDecoder(tee)
112	
113		var payload struct {
114			Model string `json:"model"`
115		}
116		if err := dec.Decode(&payload); err != nil {
117			writeError(w, http.StatusBadRequest, "invalid_request_error", "invalid JSON: "+err.Error(), "bad_request")
118			return
119		}
120		if payload.Model == "" {
121			writeError(w, http.StatusBadRequest, "invalid_request_error", "missing model field", "bad_request")
122			return
123		}
124	
125		// Reconstruct full body: captured bytes (read by decoder) + rest not yet read.
126		r.Body = io.NopCloser(io.MultiReader(&captured, r.Body))
127	
128		params, ok := g.cfg.MatchModel(payload.Model)
129		if !ok {
130			writeError(w, http.StatusNotFound, "invalid_request_error", "unknown model: "+payload.Model, "model_not_found")
131			return
132		}
133	
134		// LoadOrGet blocks until the model is healthy (or fails). The load context is
135		// detached from the caller's request context inside the manager, so a client
136		// disconnect does not abort an in-progress load that other requests may share.
137		addr, release, err := g.mgr.LoadOrGet(r.Context(), payload.Model, params)
138		if err != nil {
139			if errors.Is(err, context.DeadlineExceeded) {
140				writeError(w, http.StatusGatewayTimeout, "server_error", "model load timed out: "+err.Error(), "load_timeout")
141				return
142			}
143			writeError(w, http.StatusServiceUnavailable, "server_error", err.Error(), "model_not_loaded")
144			return
145		}
146		defer release()
147	
148		// Context window guard: reject requests that would exceed 90% of n_ctx.
149		// Best-effort: skipped when hub is nil, n_ctx is unknown, or estimation fails.
150		if g.hub != nil {
151			if nCtx := g.hub.NCtx(payload.Model); nCtx > 0 {
152				if est := estimateTokens(captured.Bytes()); est > 0 {
153					if est > nCtx*9/10 {
154						writeError(w, http.StatusBadRequest, "invalid_request_error",
155							fmt.Sprintf("estimated %d tokens exceeds context window of %d (n_ctx)", est, nCtx),
156							"context_length_exceeded")
157						return
158					}
159				}
160			}
161		}
162	
163		// Register affinity entry for the newly loaded model (idempotent for warmup models).
164		g.affinity.Register(payload.Model, params.Slots)
165	
166		// Slot affinity: read full body, compute prefix hash, inject id_slot if assigned.
167		// On any error, fall through with the original body unchanged.
168		if allBody, readErr := io.ReadAll(r.Body); readErr == nil {
169			hash := prefixHash(allBody)
170			if slotID, assigned := g.affinity.Assign(payload.Model, hash); assigned {
171				allBody = injectSlot(allBody, slotID)
172			}
173			r.Body = io.NopCloser(bytes.NewReader(allBody))
174			r.ContentLength = int64(len(allBody))
175		}
176	
177		target, parseErr := url.Parse(addr)
178		if parseErr != nil {
179			writeError(w, http.StatusInternalServerError, "server_error", "invalid backend URL", "internal_error")
180			return
181		}
182	
183		proxy := &httputil.ReverseProxy{
184			Rewrite: func(pr *httputil.ProxyRequest) {
185				pr.SetURL(target)
186				pr.Out.Host = target.Host
187			},
188			FlushInterval:  -1,
189			ModifyResponse: rewriteContextLengthError,
190			ErrorHandler: func(w http.ResponseWriter, _ *http.Request, err error) {
191				g.log.Error("proxy error", "model", payload.Model, "error", err)
192				writeError(w, http.StatusBadGateway, "server_error", "upstream error: "+err.Error(), "upstream_error")
193			},
194		}
195	
196		proxy.ServeHTTP(w, r)
197	}
198	
199	// handleModels returns all known models with their current status.
200	func (g *Gateway) handleModels(w http.ResponseWriter, _ *http.Request) {
201		type modelObj struct {
202			ID      string `json:"id"`
203			Object  string `json:"object"`
204			OwnedBy string `json:"owned_by"`
205			Status  string `json:"status,omitempty"`
206		}
207		type modelsResp struct {
208			Object string     `json:"object"`
209			Data   []modelObj `json:"data"`
210		}
211	
212		models := g.mgr.ListModels()
213		data := make([]modelObj, len(models))
214		for i, mi := range models {
215			data[i] = modelObj{
216				ID:      mi.ID,
217				Object:  "model",
218				OwnedBy: "wire",
219				Status:  mi.Status,
220			}
221		}
222	
223		w.Header().Set("Content-Type", "application/json")
224		json.NewEncoder(w).Encode(modelsResp{Object: "list", Data: data}) //nolint:errcheck
225	}
226	
227	// handleHealth returns 200 if at least one warmup model is healthy, 503 otherwise.
228	func (g *Gateway) handleHealth(w http.ResponseWriter, _ *http.Request) {
229		w.Header().Set("Content-Type", "application/json")
230		for _, name := range g.cfg.Warmup {
231			if g.mgr.Loaded(name) {
232				w.WriteHeader(http.StatusOK)
233				json.NewEncoder(w).Encode(map[string]string{"status": "ok"}) //nolint:errcheck
234				return
235			}
236		}
237		w.WriteHeader(http.StatusServiceUnavailable)
238		json.NewEncoder(w).Encode(map[string]string{"status": "degraded"}) //nolint:errcheck
239	}
240	
241	// estimateTokens approximates the token count of a request body using a
242	// chars/4 heuristic. It extracts text from messages[].content (chat) and the
243	// input field (embeddings). Returns 0 on parse failure or empty content.
244	func estimateTokens(body []byte) int {
245		var req struct {
246			Messages []struct {
247				Content json.RawMessage `json:"content"`
248			} `json:"messages"`
249			Input json.RawMessage `json:"input"`
250		}
251		if err := json.Unmarshal(body, &req); err != nil {
252			return 0
253		}
254	
255		total := 0
256		for _, msg := range req.Messages {
257			if len(msg.Content) == 0 {
258				continue
259			}
260			var s string
261			if err := json.Unmarshal(msg.Content, &s); err == nil {
262				total += len(s)
263				continue
264			}
265			var parts []struct {
266				Text string `json:"text"`
267			}
268			if err := json.Unmarshal(msg.Content, &parts); err == nil {
269				for _, p := range parts {
270					total += len(p.Text)
271				}
272			}
273		}
274	
275		if len(req.Input) > 0 {
276			var s string
277			if err := json.Unmarshal(req.Input, &s); err == nil {
278				total += len(s)
279			} else {
280				var arr []string
281				if err := json.Unmarshal(req.Input, &arr); err == nil {
282					for _, s := range arr {
283						total += len(s)
284					}
285				}
286			}
287		}
288	
289		return total / 4
290	}
291	
292	// rewriteContextLengthError inspects non-2xx upstream responses for a
293	// context_length_exceeded error code and rewrites the status to 400 to match
294	// the OpenAI API standard. llama-server returns these as 500.
295	func rewriteContextLengthError(resp *http.Response) error {
296		if resp.StatusCode >= 200 && resp.StatusCode < 300 {
297			return nil
298		}
299	
300		body, err := io.ReadAll(resp.Body)
301		resp.Body.Close()
302		if err != nil {
303			resp.Body = io.NopCloser(bytes.NewReader(nil))
304			return nil
305		}
306	
307		var envelope struct {
308			Error struct {
309				Code string `json:"code"`
310			} `json:"error"`
311		}
312		if json.Unmarshal(body, &envelope) == nil && envelope.Error.Code == "context_length_exceeded" {
313			resp.StatusCode = http.StatusBadRequest
314			resp.Status = http.StatusText(http.StatusBadRequest)
315		}
316	
317		resp.Body = io.NopCloser(bytes.NewReader(body))
318		return nil
319	}
320	
321	// writeError writes an OpenAI-format JSON error response.
322	func writeError(w http.ResponseWriter, status int, errType, message, code string) {
323		w.Header().Set("Content-Type", "application/json")
324		w.WriteHeader(status)
325		json.NewEncoder(w).Encode(map[string]any{ //nolint:errcheck
326			"error": map[string]any{
327				"message": message,
328				"type":    errType,
329				"code":    code,
330			},
331		})
332	}
