406		waitLoadedModel(t, m, "org/model-a", 10*time.Second)
407	
408		// Request model B: should evict A and load B.
409		addrB, releaseB, err := m.LoadOrGet(ctx, "org/model-b", cfg.Models["org/model-b"])
410		if err != nil {
411			t.Fatalf("LoadOrGet model-b: %v", err)
412		}
413		if addrB == "" {
414			t.Fatal("got empty addr for model-b")
415		}
416		releaseB()
417	
418		if m.Loaded("org/model-a") {
419			t.Error("model-a should have been evicted")
420		}
421		if !m.Loaded("org/model-b") {
422			t.Error("model-b should be healthy")
423		}
424	
425		// Request model A again: should evict B and reload A.
426		addrA2, releaseA2, err := m.LoadOrGet(ctx, "org/model-a", cfg.Models["org/model-a"])
427		if err != nil {
428			t.Fatalf("LoadOrGet model-a (reload): %v", err)
429		}
430		if addrA2 == "" {
431			t.Fatal("got empty addr for model-a reload")
432		}
433		releaseA2()
434	
435		if m.Loaded("org/model-b") {
436			t.Error("model-b should have been evicted on second request")
437		}
438		if !m.Loaded("org/model-a") {
439			t.Error("model-a should be healthy after reload")
440		}
441	}
442	
443	// TestLoadOrGet_InFlightProtection verifies that a model with an active
444	// in-flight request cannot be evicted; the caller gets a 503-style error.
445	func TestLoadOrGet_InFlightProtection(t *testing.T) {
446		cfg := &config.Config{
447			Models: map[string]config.ModelParams{
448				"org/model-a": {Slots: 1},
449				"org/model-b": {Slots: 1},
450			},
451			Warmup:    []string{"org/model-a"},
452			MaxModels: 1,
453		}
454		m := newTestManager(cfg)
455	
456		ctx, cancel := context.WithCancel(context.Background())
457		defer cancel()
458		if err := m.Start(ctx); err != nil {
459			t.Fatalf("Start: %v", err)
460		}
461	
462		waitLoadedModel(t, m, "org/model-a", 10*time.Second)
463	
464		// Hold an in-flight request against model A.
465		_, releaseA, err := m.LoadOrGet(ctx, "org/model-a", cfg.Models["org/model-a"])
466		if err != nil {
467			t.Fatalf("LoadOrGet model-a: %v", err)
468		}
469		// Do NOT call releaseA yet — this keeps inflight > 0.
470	
471		// Requesting model B at max_models=1 must fail because A has in-flight requests.
472		_, _, err = m.LoadOrGet(ctx, "org/model-b", cfg.Models["org/model-b"])
473		if err == nil {
474			t.Fatal("expected error when trying to evict a model with in-flight requests, got nil")
475		}
476	
477		// Now release A; the next request for B should succeed.
478		releaseA()
479	
480		_, releaseB, err := m.LoadOrGet(ctx, "org/model-b", cfg.Models["org/model-b"])
481		if err != nil {
482			t.Fatalf("LoadOrGet model-b after release: %v", err)
483		}
484		releaseB()
485	}
486	
487	// TestLoadOrGet_ContextCancellation verifies that cancelling the requesting
488	// context does not abort the model load. A second request for the same model
489	// (with a valid context) should join the in-progress load.
490	func TestLoadOrGet_ContextCancellation(t *testing.T) {
491		cfg := &config.Config{
492			Models:    map[string]config.ModelParams{"org/model-a": {Slots: 1}},
493			MaxModels: 1,
494		}
495		m := New(cfg, slog.Default())
496		// 400 ms delay so we can cancel the first request mid-load.
497		m.cmdBuilder = testCmdBuilderWithDelay(400)
498	
499		bgCtx, cancel := context.WithCancel(context.Background())
500		defer cancel()
501		if err := m.Start(bgCtx); err != nil {
502			t.Fatalf("Start: %v", err)
503		}
504	
505		params := config.ModelParams{Slots: 1}
506	
507		// First request: cancel the context almost immediately.
508		cancelCtx, cancelFn := context.WithCancel(bgCtx)
509		cancelFn() // cancel before LoadOrGet returns
510	
511		_, _, err := m.LoadOrGet(cancelCtx, "org/model-a", params)
512		if err == nil {
513			t.Log("first request: LoadOrGet returned before context cancelled (load was fast)")
514		} else if err != context.Canceled {
515			t.Fatalf("first request: expected context.Canceled, got %v", err)
516		}
517	
518		// The supervisor should still be running (using the manager's detached context).
519		// A second request with a valid context should succeed.
520		addr, release, err := m.LoadOrGet(bgCtx, "org/model-a", params)
521		if err != nil {
522			t.Fatalf("second LoadOrGet: %v", err)
523		}
524		defer release()
525		if addr == "" {
526			t.Fatal("second LoadOrGet: got empty addr")
527		}
528	}
529	
530	// TestLoadOrGet_LoadFailure verifies that when a model fails to start, all
531	// concurrent waiters receive an error and the model is removed from procs.
532	func TestLoadOrGet_LoadFailure(t *testing.T) {
533		cfg := &config.Config{
534			Models:    map[string]config.ModelParams{"org/bad-model": {Slots: 1}},
535			MaxModels: 2,
536		}
537		m := New(cfg, slog.Default())
538		m.cmdBuilder = failCmdBuilder            // process exits immediately
539		m.healthTimeout = 500 * time.Millisecond // short timeout so test is fast
540	
541		bgCtx, cancel := context.WithCancel(context.Background())
542		defer cancel()
543		if err := m.Start(bgCtx); err != nil {
544			t.Fatalf("Start: %v", err)
545		}
546	
547		params := config.ModelParams{Slots: 1}
548		const n = 5
549		var wg sync.WaitGroup
550		errs := make([]error, n)
551		wg.Add(n)
552		for i := range n {
553			go func(i int) {
554				defer wg.Done()
555				_, _, errs[i] = m.LoadOrGet(bgCtx, "org/bad-model", params)
556			}(i)
557		}
558		wg.Wait()
559	
560		// All waiters must have received an error.
561		for i, err := range errs {
562			if err == nil {
563				t.Errorf("goroutine %d: expected load error, got nil", i)
564			}
565		}
566	
567		// Model must not appear in ListModels (state idle = excluded).
568		for _, mi := range m.ListModels() {
569			if mi.ID == "org/bad-model" {
570				t.Errorf("failed model still visible in ListModels with status %q", mi.Status)
571			}
572		}
573	}
574	
575	// TestLoadOrGet_CapacityLimit verifies that when max_models=2 and both loaded
576	// models have in-flight requests, a third request returns an error.
577	func TestLoadOrGet_CapacityLimit(t *testing.T) {
578		cfg := &config.Config{
579			Models: map[string]config.ModelParams{
580				"org/model-a": {Slots: 1},
581				"org/model-b": {Slots: 1},
582			},
583			MaxModels: 2,
584		}
585		m := newTestManager(cfg)
586	
587		bgCtx, cancel := context.WithCancel(context.Background())
588		defer cancel()
589		if err := m.Start(bgCtx); err != nil {
590			t.Fatalf("Start: %v", err)
591		}
592	
593		params := config.ModelParams{Slots: 1}
594	
595		// Load both models and hold in-flight requests.
596		_, releaseA, err := m.LoadOrGet(bgCtx, "org/model-a", params)
597		if err != nil {
598			t.Fatalf("LoadOrGet model-a: %v", err)
599		}
600		_, releaseB, err := m.LoadOrGet(bgCtx, "org/model-b", params)
601		if err != nil {
602			t.Fatalf("LoadOrGet model-b: %v", err)
603		}
604	
605		// Third model with both in-flight: must fail.
606		_, _, err = m.LoadOrGet(bgCtx, "org/model-c", config.ModelParams{Slots: 1})
607		if err == nil {
608			t.Fatal("expected capacity error for third model with all models busy, got nil")
609		}
610	
611		releaseA()
612		releaseB()
613	}
614	
615	// ---------------------------------------------------------------------------
616	// Helpers
617	// ---------------------------------------------------------------------------
618	
619	// waitLoadedModel polls until the named model is healthy or the deadline passes.
620	func waitLoadedModel(t *testing.T, m *Manager, name string, timeout time.Duration) {
621		t.Helper()
622		deadline := time.Now().Add(timeout)
623		for time.Now().Before(deadline) {
624			if m.Loaded(name) {
625				return
626			}
627			time.Sleep(100 * time.Millisecond)
628		}
629		t.Fatalf("model %q did not become healthy within %v", name, timeout)
630	}
